window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["05"]={"https://www.gov.uk/foreign-travel-advice/barbados":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"2784fd4d2ae630c2c32f22a17b4cb587d08c1670a9fe4d507959cc624cad4285","read":"https://www.gov.uk/api/content/foreign-travel-advice/barbados","bytes":56428,"x":"fulltext v1","title":"Barbados travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-18T14:55:54+00:00","mod":"2026-01-23T15:06:44+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/barbados/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Barbados set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Barbados High Commission in the UK","https://www.gov.uk/government/publications/foreign-embassies-in-the-uk"],":"]},{"k":"p","s":["1 Great Russell Street, London WC1B 3N"]},{"k":"p","s":["Phone: 020 7299 7150 Fax: 020 7323 6872 Email: london@foreign.gov.bb"]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must be valid for the planned length of your stay."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You do not need a visa to visit Barbados."]},{"k":"p","s":["You will be told how long you can stay when you arrive. If you want to extend your stay, you must apply and pay for an extension through the ",["Barbados Immigration Department","https://immigration.gov.bb/"],"."]},{"k":"p","s":["It’s illegal to overstay or work without a ",["work permit","https://immigration.gov.bb/pages/WorkPermit.aspx"],". The Barbados authorities could fine or detain you if you overstay."]},{"k":"p","s":["Visitors must be able to show an onward or return ticket in order to enter the country."]},{"k":"hs","s":["Immigration and customs form"]},{"k":"p","s":["All travellers must ",["fill in an immigration and customs form online","https://travelform.gov.bb/"]," before they arrive."]},{"k":"h","s":["Children and young people"]},{"k":"p","s":["Check the ",["rules for travelling with children and young people to Barbados","https://immigration.gov.bb/pages/visitor.aspx"]," from the Barbados Immigration Department."]},{"k":"h","s":["Departure tax"]},{"k":"p","s":["All passengers aged 2 years and older must pay a departure tax of 55 Barbados dollars (27.50 US dollars). Passengers travelling outside the Caribbean region pay an additional 70 US dollars per person, and those travelling within the Caribbean pay an additional 20 US dollars per person."]},{"k":"p","s":["Most airlines include the cost within the ticket price. Check details with your airline or tour operator."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Barbados, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Barbados guide","https://travelhealthpro.org.uk/country/23/barbados#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods that can be brought into and taken out of Barbados","https://www.visitbarbados.org/plan-your-trip/important-information"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Barbados"]},{"k":"p","s":["Although there’s no recent history of terrorism in Barbados, attacks cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"p","s":["There have been incidents of violent crime, including:"]},{"k":"li","s":["armed robbery"]},{"k":"li","s":["sexual assault"]},{"k":"li","s":["gang-related shootings"]},{"k":"li","s":["carjackings"]},{"k":"p","s":["There has been an increase in gang-related murders involving guns. Some incidents have taken place in populated and public areas."]},{"k":"p","s":["Take sensible precautions to protect your personal safety:"]},{"k":"li","s":["make sure your accommodation is secure"]},{"k":"li","s":["take care when walking alone off busy main roads and taking money from ATMs"]},{"k":"li","s":["avoid isolated areas, including beaches, particularly after dark"]},{"k":"li","s":["only use licensed taxis"]},{"k":"li","s":["take particular care around large gatherings, including street and beach parties, especially after dark or during the festival season"]},{"k":"li","s":["do not carry large amounts of cash or wear expensive-looking jewellery"]},{"k":"li","s":["leave valuables and travel documents in a safety deposit box or secure hotel safe"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Illegal drugs penalties"]},{"k":"p","s":["It is illegal to possess drugs. There are severe penalties for all drug offences. Pack your luggage yourself and do not carry anything through customs for anyone else."]},{"k":"hs","s":["Camouflage clothing"]},{"k":"p","s":["It is illegal for anyone, including children, to wear camouflage clothing."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["In the Caribbean, attitudes towards the LGBT+ community are mostly conservative. It is uncommon for opposite or same-sex couples to show affection in public, for example, holding hands or kissing. Doing this may attract unwanted and negative attention. Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Swimming safety"]},{"k":"p","s":["Always take great care when swimming. Currents can be deceptively strong, including on some of the popular beaches on the south and west coasts. Some beaches do not have lifeguards or warning flags. Existing lifeguard stations are not manned 24hrs a day. Motorized water sports equipment, including jet skis, dive boats on snorkelling tours, and catamarans, may operate near to the shore. Be mindful of these as well as other swimmers who may use non-motorised, large water equipment like surfboards."]},{"k":"p","s":["Swimming is not recommended on many of the east-coast beaches where currents are particularly strong. Follow local warnings."]},{"k":"p","s":["See ",["water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Barbados, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and ",["Barbados driving tips","https://barbados.org/tours/barbados-driving-tips.htm"],"."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Taxis do not have meters. There are standard fares for most destinations. Agree the fare in Barbados dollars with the driver before you set off. Drivers do not always accept card payments, so carry cash with you."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Hurricanes"]},{"k":"p","s":["The hurricane season normally runs from June to November. Monitor local news and check ",["World Meteorological Organization weather reports for Barbados","https://severeweather.wmo.int/"]," and the ",["National Hurricane Center","https://www.nhc.noaa.gov/"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["Earthquakes are a potential risk in Barbados, and there are occasional tremors. Follow the advice of the local authorities."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"hs","s":["Volcanic eruptions"]},{"k":"p","s":["Check the ",["alert level of the underwater volcano ‘Kick ‘em Jenny’","https://uwiseismic.com/volcanoes/kick-em-jenny/kej-monitoring/"],", located 5 miles off the coast of Grenada. Observe any maritime exclusion zones and follow the advice of the local authorities if there is increased activity or an eruption."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 511 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Barbados","https://travelhealthpro.org.uk/country/23/barbados#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Barbados","https://travelhealthpro.org.uk/country/23/barbados"],", including:"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["dengue"]},{"k":"li","s":["chikungunya"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Barbados"]},{"k":"p","s":["The Barbados healthcare system is not as extensive as the UK. Queen Elizabeth Hospital can cope with many types of treatment, but serious cases may need emergency evacuation. You can ",["call the hospital helpline","https://www.qehconnect.com/contact-us/"]," to speak with a healthcare professional."]},{"k":"p","s":["Medical treatment in Barbados can be expensive. Check private clinics’ prepayment policies, as they may not accept medical travel insurance as payment."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Barbados","https://www.gov.uk/government/publications/barbados-list-of-medical-facilities-practioners"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Barbados"]},{"k":"p","s":["Ambulance: 511"]},{"k":"p","s":["Fire: 311"]},{"k":"p","s":["Police: 211"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Barbados"]," and ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Barbados"]," in Barbados"]},{"k":"li","s":["dealing with a ",["death in Barbados","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-barbados"]]},{"k":"li","s":["being ",["arrested in Barbados","https://www.gov.uk/government/publications/barbados-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/barbados/british-high-commission-bridgetown"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/barbados/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Barbados","https://www.gov.uk/government/publications/overseas-business-risk-barbados"]," on how to manage political, economic, and business security-related risks."]}],"chars":10798,"change":"Removal of information about flight disruptions ('Warnings and insurance' page)."},"https://theconversation.com/what-tommy-robinsons-conviction-tells-us-about-the-cost-to-journalists-reporting-in-the-public-interest-295890":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"8c56c04de408466c16dbe28cc1b1b66fd3022f0b016829a0dc285d447259a9d1","read":"https://theconversation.com/what-tommy-robinsons-conviction-tells-us-about-the-cost-to-journalists-reporting-in-the-public-interest-295890","bytes":181549,"x":"fulltext v1","title":"What Tommy Robinson’s conviction tells us about the cost to journalists reporting in the public interest","by":[{"n":"Tom Felle","r":"Associate Professor of Journalism, University of Galway"}],"pub":"2026-11-06T12:04:43Z","mod":"","blocks":[{"k":"p","s":["During the unrest that followed the 2024 Southport murders, British tabloid the Daily Mail reported on the activities of far-right activist Tommy Robinson. The story was covered by freelance reporter Andrew Young, and edited by the Mail’s own Jacob Dirnhuber."]},{"k":"p","s":["On October 28, ",["Robinson","https://theconversation.com/topics/tommy-robinson-24490"]," was convicted for threatening and harassing Young and Dirnhuber. A jury at Southwark Crown Court in London found Robinson guilty of ",["two counts of harassment causing fear of violence","https://www.itv.com/news/2026-10-28/tommy-robinson-could-face-jail-for-harassing-two-daily-mail-journalists"],", an offence with a maximum sentence of ten years. The judge will sentence him on December 16."]},{"k":"p","s":["Robinson, whose real name is Stephen Yaxley-Lennon, ",["hired private investigators","https://news.sky.com/story/tommy-robinson-found-guilty-of-harassing-two-journalists-13604466"]," to find the journalists’ home addresses. He messaged Dirnhuber saying “I’ll be knocking at your door”, and told Young by phone “I’m coming to get you”. He also posted images of Dirnhuber outside his home, and of Young’s family."]},{"k":"p","s":["Before Robinson’s conviction, Young was given a ",["close protection officer","https://www.itv.com/news/2026-10-28/tommy-robinson-could-face-jail-for-harassing-two-daily-mail-journalists"],", while Dirnhuber was forced to move house."]},{"k":"p","s":["Anyone is entitled to criticise the Daily Mail or challenge its reporting. In a democratic society, any member of the public must be free to challenge what journalists publish. But journalists must also be free to report without fearing threats of violence, whether online or in their homes."]},{"k":"p","s":["In reality, threats to reporters’ homes and families, along with online abuse and physical intimidation, have become ",["so pervasive","https://www.gov.uk/government/publications/uk-journalist-safety-research-2026/uk-journalist-safety-research-2026"]," that they are treated as part of the job in Britain and well beyond it."]},{"k":"p","s":["Few of these cases end up in front of a jury, yet Robinson’s conviction shows that the law can respond. Prosecutors ",["told an earlier hearing","https://www.lbc.co.uk/article/tommy-robinson-journalist-court-5Hjd6jz_2/"]," that none of the alleged harassment contained a direct threat of violence, and the jury still convicted."]},{"k":"p","s":["Robinson’s victims had a national newspaper behind them, but many journalists have no such support. When threats make journalists or their editors think twice about a story, the public loses out, usually without ever knowing."]},{"k":"p","s":["Read more: ",["The enduring power of journalism in a world of more media and less freedom","https://theconversation.com/the-enduring-power-of-journalism-in-a-world-of-more-media-and-less-freedom-271781"]]},{"k":"h","s":["A growing threat"]},{"k":"p","s":["The Robinson case is one among many, and around the world journalists are increasingly under threat for doing their jobs. The Committee to Protect Journalists found a record ",["129 journalists and media workers were killed in 2025","https://cpj.org/2026/02/record-number-of-journalists-killed-in-2025-israel-responsible-for-two-thirds-of-deaths/"],", more than three-quarters of them in conflict settings."]},{"k":"p","s":["Europe is not immune: hired killers ",["murdered Daphne Caruana Galizia in Malta in 2017","https://www.icij.org/inside-icij/2022/10/two-brothers-convicted-of-murdering-daphne-caruana-galizia-sentenced-to-40-years-in-prison/"],", and ",["Ján Kuciak in Slovakia in 2018","https://cpj.org/data/people/jan-kuciak/"],", both investigative journalists."]},{"k":"p","s":["Most threats never come near that point, but they are very common. In a ",["2020 global survey","https://www.icfj.org/our-work/chilling-global-study-online-violence-against-women-journalists"]," by UNESCO and the International Center for Journalists, 73% of the women journalists who responded had experienced online attacks, and one in five reported being attacked or abused offline in connection with it."]},{"k":"p","s":["In ",["research commissioned by the UK government","https://www.gov.uk/government/publications/uk-journalist-safety-research-2026/uk-journalist-safety-research-2026"]," and published in July this year, 72% of the 531 journalists surveyed had experienced harassment, abuse, threats or legal intimidation. Among those affected, almost half said safety concerns had made them hesitate before reporting certain stories."]},{"k":"p","s":["These figures should concern anyone who relies on journalists to uncover what those in power would prefer to keep quiet."]},{"k":"p","s":["Read more: ",["Four major threats to press freedom in the UK","https://theconversation.com/four-major-threats-to-press-freedom-in-the-uk-228932"]]},{"k":"h","s":["The toll of online abuse"]},{"k":"p","s":["Online abuse is far more pervasive than physical violence, and it takes a heavy toll. Among those affected in the aforementioned UK government survey, 78% had faced online abuse, compared with 11% who had been physically attacked. Just over half said safety concerns had damaged their wellbeing, and almost one in four had considered leaving journalism."]},{"k":"p","s":["Female journalists are at an ",["increased risk of being targeted","https://reutersinstitute.politics.ox.ac.uk/uk-journalists-2020s/6-safety-threats-experienced-uk-journalists-and-their-physical-emotional"],". In a ",["2026 UN Women study","https://www.unwomen.org/en/news-stories/press-release/2026/04/reports-to-police-of-online-violence-against-women-journalists-double-since-2020-with-one-in-four-experiencing-related-anxiety-andor-depression"],", nearly a quarter of female journalists and media workers surveyed had been diagnosed with or treated for anxiety or depression linked to online violence. Some 45% said they self-censored on social media to avoid abuse – a 50% increase on 2020 – and more than one in five self-censored in their day-to-day work."]},{"k":"p","s":["My ",["own research on abuse of women in Irish politics","https://www.independent.ie/irish-news/failure-to-address-cyber-violence-against-women-in-politics-may-silence-womens-voices-galway-academic/a/135130489.html"]," raises a related question about who can afford to stay visible in public life when doing so exposes them to threats."]},{"k":"p","s":["Reporting the abuse often brings little relief. Only 17% of affected journalists in the UK government survey had gone to the police, and a little over one in four of those found it effective. Of those who reported to online platforms, just 5% found that route effective."]},{"k":"p","s":["The Daily Mail deserves credit for standing by its journalists, but not every news organisation can afford to do the same, and many freelancers have no one to call. If reporters fear for their safety because of online or offline threats, stories will go untold, and those in power will face fewer questions. Democracy will suffer as a result, and we all lose out."]}],"chars":4825},"https://www.gov.uk/foreign-travel-advice/georgia":{"r":"govuk","at":"2026-11-17T16:38Z","sha":"91bdaeab23d97c4f257958ae9e39cdcf03b80919dfed1fcb8bc22009e2a34c38","read":"https://www.gov.uk/api/content/foreign-travel-advice/georgia","bytes":83815,"x":"fulltext v1","title":"Georgia travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-22T00:00:00+00:00","mod":"2026-11-12T16:54:23+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["South Ossetia and Abkhazia"]},{"k":"p","s":["For security reasons, FCDO advises against all travel to the Russian occupied regions of:"]},{"k":"li","s":["South Ossetia"]},{"k":"li","s":["Abkhazia"]},{"k":"p","s":["FCDO also advises against all but essential travel to areas immediately next to the administrative boundary lines with South Ossetia and Abkhazia."]},{"k":"p","s":["FCDO cannot provide face-to-face support to British nationals travelling in South Ossetia and Abkhazia, as UK government employees are restricted from travelling there."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/georgia/regional-risks"],"."]},{"k":"h","s":["Global travel impacts due to escalation in the Middle East"]},{"k":"p","s":["Escalation in the Middle East has caused widespread travel disruption, including airspace closures, delayed and cancelled flights."]},{"k":"p","s":["Your travel plans may be affected, even if your destination is not in the Middle East. Before you travel:"]},{"k":"li","s":["check travel advice for any countries or territories you are transiting through"]},{"k":"li","s":["check for the latest updates from your airline or tour operator"]},{"k":"li","s":["review your travel insurance policy for coverage"]},{"k":"li","s":["monitor local and international media for the latest information and sign up for travel advice email alerts"]},{"k":"p","s":["If you have been impacted by travel disruption and need to review your visa contact the ",["Ministry of Foreign Affairs of Georgia","https://new.geoconsul.gov.ge/en"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/georgia/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Georgia’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Georgia set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Georgian Embassy in the UK","https://uk.mfa.gov.ge/en"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["If you’re visiting Georgia, your passport should be valid for the duration of your stay."]},{"k":"p","s":["Check with your travel provider to make sure your passport and other travel documents meet their requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can visit Georgia without a visa for up to one year."]},{"k":"p","s":["To stay longer or to travel for work or study, you must apply for a longer-term visa. Contact the ",["Georgian Ministry of Foreign Affairs","https://new.geoconsul.gov.ge/en"]," for more information."]},{"k":"p","s":["The rules on who can work in Georgia were changed on 1 March 2026. If you are a foreign national and want to work in Georgia, including working remotely or running a business, you must have a work permit."]},{"k":"p","s":["A work permit is issued for one year and only for a specific job and a specific employer."]},{"k":"p","s":["Once the work permit is approved, you must then apply for the appropriate visa and/or a worker’s residence permit."]},{"k":"p","s":["To apply for a work permit or get more information, contact the ",["State Employment Support Agency","https://moh.gov.ge/"]," under the Ministry of Internally Displaced Persons from the Occupied Territories, Labour, Health and Social Affairs of Georgia."]},{"k":"p","s":["If you’re in Georgia for more than 183 days and do any paid employment, you’re automatically liable for income tax and must tell the ",["Revenue Service of Georgia","https://rs.ge/Home-en"],". You’ll be fined if you do not comply."]},{"k":"h","s":["Entering or leaving Georgia"]},{"k":"p","s":["A small number of British citizens have either been denied entry to Georgia or had trouble leaving. These cases appear to be linked to alleged presence at or participation in political demonstrations, and unpaid fines."]},{"k":"p","s":["Some families have reported being denied entry to Georgia due to their child’s passport photo no longer matching their current appearance."]},{"k":"h","s":["Insurance upon entry"]},{"k":"p","s":["All visitors must have appropriate health and accident insurance to cover all healthcare needs during your visit. You may be asked for evidence of this, either by your airline at check-in or by immigration authorities when you arrive in Georgia. You may face difficulties if you do not have this evidence."]},{"k":"p","s":["Make sure you have ",["appropriate travel health insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," and accessible funds to cover the cost of any medical treatment abroad and repatriation. The insurance coverage amount must be no less than 30 000 Georgian Lari. The insurance policy may be issued by either a Georgian or a foreign insurance company."]},{"k":"p","s":["The insurance policy needs to cover the full period of your stay in Georgia, including both arrival and departure dates."]},{"k":"p","s":["See ",["Georgian Visa information","https://geoconsul.gov.ge/en/entering-georgia"]," for full details, including mandatory information that must be included in the insurance policy."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Georgia guide","https://travelhealthpro.org.uk/country/87/georgia#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Georgia","https://www.rs.ge/LegalEntityCustomsProcedures-en?cat=1&tab=1"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Bringing medicines into Georgia"]},{"k":"p","s":["Georgia has a very strict anti-drugs policy. This covers prescription and non-prescription medicines commonly available in the UK. For example, non-prescription medicines containing codeine are illegal. This can cause serious problems for travellers and in some cases lead to criminal prosecution. Do not carry medicine that is illegal in Georgia. Even with a valid prescription, foreign nationals have been detained, prosecuted, and fined."]},{"k":"p","s":["For more information on the legal status of a specific medicine, contact the ",["Revenue Service of Georgia","https://rs.ge/Home-en"]," or the ",["Georgian Embassy in the UK","https://uk.mfa.gov.ge/en"],"."]},{"k":"p","s":["If you travel with prescription medicine that is legal in Georgia, you must carry a doctor’s prescription and the original packaging. You should check in advance if your prescription would be acceptable to the Georgian authorities and whether the medicine you carry needs a prescription. You can contact the State Regulation Agency for Medical and Pharmaceutical Activities via email: regagency@moh.gov.ge. Assessment of your enquiry will take approximately one month."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Georgia","https://www.gov.uk/foreign-travel-advice/georgia/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Georgia"]},{"k":"p","s":["Terrorist attacks in Georgia cannot be ruled out. Attacks could happen anywhere and affect western interests and places visited by foreigners, such as tourist sites and cultural events."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["28 October marked the 700th consecutive day of protests. Some of these have led to violent confrontation between police and protesters. In Tbilisi the demonstrations are now mainly focused on the Parliament building on Rustaveli Avenue, but they can spread to other areas, particularly on Saturday evenings/nights and on the anniversaries of significant political events. Demonstrations also take place in other cities and towns. Demonstrations may lead to travel disruption."]},{"k":"p","s":["Tensions can escalate without warning. You should:"]},{"k":"li","s":["check local media"]},{"k":"li","s":["avoid large gatherings and demonstrations"]},{"k":"li","s":["follow the advice of local authorities"]},{"k":"p","s":["If you participate or engage in political demonstrations, you may face additional questioning on exit or be refused re-entry to Georgia."]},{"k":"p","s":["If you have unpaid fines, you may be refused exit until these are paid."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Crime levels are low. You should:"]},{"k":"li","s":["take sensible precautious to avoid pick-pocketing, particularly in crowded places"]},{"k":"li","s":["not leave valuables unattended"]},{"k":"li","s":["stay aware of your surroundings"]},{"k":"li","s":["always keep your mobile phone charged and with you"]},{"k":"p","s":["Georgian law protects everyone’s human rights and equality, but ethnic minorities and LGBT+ people may face discrimination. Harassment and assault based on race does take place. Those perceived as being part of or supporting the LGBT+ community may face harassment and assault."]},{"k":"p","s":["If someone attempts to assault you or you feel threatened, call the emergency number 112 and ask for the police."]},{"k":"hs","s":["Drink spiking"]},{"k":"p","s":["There have been reports of drink spiking in Georgia. Be wary of strangers approaching you to take you to a restaurant or nightclub. If strangers offer you food and drink these items may contain drugs that could put you at risk. Buy your own drinks and always keep sight of them to avoid them being spiked."]},{"k":"p","s":["For more information about spiking, read Travel Aware’s information on ",["Spiking and methanol poisoning","https://travelaware.campaign.gov.uk/spiking-and-methanol-poisoning/?_gl=1*1m0ptxg*_ga*MTMyMzMzNDQ0Mi4xNzI1OTU1OTIw*_ga_S5RQ7FTGVR*czE3NTQ5MDI5NDIkbzU5JGcxJHQxNzU0OTA0NDU0JGozNCRsMCRoMA.."],"."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["You are not legally required to always carry ID, but if the police or a service provider (hotel, bank etc) ask you for ID you are expected to show your passport."]},{"k":"hs","s":["Dress codes and behaviour in public"]},{"k":"p","s":["Tbilisi is a cosmopolitan city. There can be more conservative attitudes in rural areas. When travelling outside cities, be aware of cultural sensitivities around modest dress (particularly in places of worship) and showing affection in public."]},{"k":"hs","s":["Money"]},{"k":"p","s":["Prices may be quoted in US dollars and euros, but goods and services must be paid for in local currency (lari)."]},{"k":"p","s":["Travellers’ cheques are rarely accepted. Outside major towns, you may not find ATMs or be able to use credit and debit cards. Take enough cash in lari if travelling to rural or remote areas."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Illegal drugs, including cannabis, carry severe penalties. You should expect a long jail sentence of 5 to 25 years and heavy fines for possessing, using, or smuggling of illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Georgia have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Using cameras"]},{"k":"p","s":["Do not photograph sensitive sites like military bases and power installations."]},{"k":"p","s":["Be aware of cultural sensitivities when photographing churches and other religious sites."]},{"k":"hs","s":["Using Drones"]},{"k":"p","s":["You must ",["register any drone with a video or audio recording system","https://uas.gov.ge/EN"]," at the Georgian Civil Aviation Agency before it can be used in a public place. To register you need your passport and a valid email address. Foreign nationals cannot register drones online, so you will need to do this in person at the Civil Aviation Agency office."]},{"k":"p","s":["You must get a special licence from the Civil Aviation Authority for any drone that weighs more than 250g but less than 25kg, even if it does not have a video or audio system."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is legal in Georgia, and there are anti-discrimination laws, but same-sex relationships are still not widely accepted."]},{"k":"p","s":["Showing affection in public may result in discrimination or harassment. Homophobic harassment and assault take place."]},{"k":"p","s":["Pride marches in 2019 and 2021 were cancelled because the police did not guarantee security. In 2023, a Pride event was cancelled after a violent protest."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Surrogacy"]},{"k":"p","s":["The Georgian Parliament is expected to adopt a law banning surrogacy for foreign couples soon. Keep up to date and ",["get emails when we update Georgia travel advice","https://www.gov.uk/foreign-travel-advice/georgia/email-signup"],"."]},{"k":"p","s":["If you’re visiting Georgia to arrange an international surrogacy, consider the risks and challenges involved. Surrogacy is a complex, lengthy process. You should:"]},{"k":"li","s":["make sure you’re aware of the facts and well-prepared before starting the process"]},{"k":"li","s":["get specialist legal advice on Georgian and UK laws before making any arrangements"]},{"k":"li","s":["read FCDO and Home Office ",["guidance on surrogacy overseas","https://www.gov.uk/government/publications/surrogacy-overseas"]]},{"k":"li","s":["research clinics and hospitals thoroughly to make sure they are safe and reputable"]},{"k":"p","s":["The British Embassy cannot get involved in surrogacy arrangements or recommend hospitals or clinics."]},{"k":"p","s":["Commissioning a surrogacy will not automatically mean that the child holds British citizenship. To bring your child born through surrogacy from Georgia to the UK, you must ",["apply for a full British passport","https://www.gov.uk/overseas-passports"],". You need a Georgian birth certificate for this. Check the ",["Public Service Hall","https://psh.gov.ge/main/menus/1"]," and ",["Service Development Agency","https://sda.gov.ge/?page_id=7313&lang=en"]," websites and research the rules for leaving the country with children (some legal details are in Georgian only). You can stay visa-free in Georgia for a continuous period of up to one year. The ",["Georgian Ministry of Foreign Affairs","https://geoconsul.gov.ge/"]," has more information."]},{"k":"hs","s":["Trade with South Ossetia and Abkhazia"]},{"k":"p","s":["Anyone trading with Abkhazia and South Ossetia must have a licence issued by the Georgia government. This includes buying and selling property and most financial transactions. Anyone trading without a licence may face penalties under Georgian civil and criminal law."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["Make sure your ",["travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," covers your activities."]},{"k":"p","s":["If you get into trouble during hiking, skiing, adventure travel or extreme sports, the emergency response may be limited."]},{"k":"p","s":["Off-piste skiing is very dangerous. It can be difficult to get accurate information on mountain conditions, including avalanche risks. Read ",["preparing for winter sports abroad","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],"."]},{"k":"p","s":["If you’re doing extreme sports, consider going with specialist guides. Many insurance policies will not cover damage to rental equipment or skiing off-piste without a guide."]},{"k":"p","s":["Be aware that safety standards in Georgia may not be as high as those in the UK. For example, several people were injured when a ski lift at Gudauri malfunctioned in 2018 and a tourist helicopter crashed near Stepantsminda (Kazbegi) in 2019."]},{"k":"p","s":["If you plan to hike close to the administrative boundary lines, consider hiring a professional guide."]},{"k":"h","s":["Transport risks"]},{"k":"p","s":["Take usual precautions after dark in unfamiliar areas."]},{"k":"p","s":["Street lighting away from main roads can be poor and pavements uneven. There may be occasional short power cuts – consider carrying a torch."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Taxi provision and safety has improved significantly. To stay safe using taxis:"]},{"k":"li","s":["do not flag taxis in the street"]},{"k":"li","s":["try to pre-book taxis through an app"]},{"k":"li","s":["check the taxi has working seatbelts"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you’re planning to drive in Georgia, see information on ",["driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Georgia guide","https://www.rac.co.uk/drive/travel/country/georgia/"],"."]},{"k":"p","s":["You can drive in Georgia with a UK driving licence for up to one year. If you’re hiring a car, check with the car hire company before you travel whether they will accept the UK licence or whether you will need a ",["1968 international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"],". You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["Drink driving punishments can be severe. Georgia has a lower blood alcohol content limit than the UK, so avoid alcohol if driving."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Take care when driving, especially at night. Be aware that:"]},{"k":"li","s":["roads outside city centres are often badly lit and poor quality"]},{"k":"li","s":["stray livestock can be a hazard"]},{"k":"li","s":["road markings and the right of way can be confusing"]},{"k":"li","s":["many cars are poorly maintained"]},{"k":"li","s":["driving can be erratic"]},{"k":"li","s":["heavy rain, flooding and snow at higher altitudes can affect roads and bridges making travel difficult or impossible (particularly in remote areas)"]},{"k":"li","s":["landslides are common"]},{"k":"p","s":["Construction work is currently ongoing in the vicinity of central Tbilisi."]},{"k":"p","s":["If you’re travelling outside Tbilisi, particularly in remote areas, make sure your vehicle is suitable for off-road driving and check weather conditions locally. Access to medical facilities may be limited in remote areas, and available facilities may not have modern medical equipment."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["Take usual precautions with your personal safety and belongings. Compartments on sleeper trains usually have locks."]},{"k":"p","s":["There is a daily train service between Georgia and Azerbaijan."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There are frequent small earthquakes in Georgia. The most recent significant earthquake took place in 2022 – a 6.2 magnitude earthquake struck 104km south-west of Tbilisi."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about what to do before, during and after an earthquake."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["Lightning and wildfires are a risk in summer, particularly in the mountains."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Georgia. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read FCDO’s ",["overall travel advice","https://www.gov.uk/foreign-travel-advice/georgia/warnings-and-insurance"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/georgia/safety-and-security"],"."]},{"k":"h","s":["South Ossetia and Abkhazia"]},{"k":"p","s":["For security reasons, FCDO advises against all travel to the Russian occupied regions of:"]},{"k":"li","s":["South Ossetia"]},{"k":"li","s":["Abkhazia"]},{"k":"p","s":["FCDO also advises against all but essential travel to areas immediately next to the administrative boundary lines with South Ossetia and Abkhazia."]},{"k":"p","s":["The administrative boundary lines with the Russian occupied regions of Abkhazia and South Ossetia are generally unmarked and away from roads. Take care not to cross the lines – you could be arrested by the region’s self-declared authorities."]},{"k":"p","s":["The Georgia and UK governments do not recognise the unilateral declarations of independence by the Russian occupied regions of South Ossetia and Abkhazia. Following international law, the Georgian government claims the right to exercise sovereignty in these territories. The UK government, along with almost all other states, recognises Georgia’s right to do this."]},{"k":"p","s":["Consular support is not available in Abkhazia and South Ossetia."]},{"k":"hs","s":["Buying property in South Ossetia and Abkhazia"]},{"k":"p","s":["Ownership of many properties in these regions is disputed. There are thousands of claims to property ownership from people displaced by conflicts following the collapse of the USSR."]},{"k":"p","s":["Buying these properties could have serious financial and legal implications, including legal proceedings in Georgia’s courts and enforcement of court judgements elsewhere in Europe. If territorial disputes are settled, this could have consequences. For example, property may need to be returned to its original owners (property restitution)."]},{"k":"h","s":["Travel to and from Russia"]},{"k":"p","s":["It is illegal under Georgian law to enter Georgia from Russia through South Ossetia or Abkhazia. If you do this, you could get heavy fines or a prison sentence of up to 4 years. If your passport has entry or exit stamps from the self-declared authorities in these regions, Georgian authorities may see this as illegal entry through an unrecognised border crossing."]},{"k":"p","s":["If you’re considering entering Russia by crossing Georgia-Russia land borders, check ",["Russia travel advice","https://www.gov.uk/foreign-travel-advice/russia"],". FCDO advises against all travel to Russia."]},{"k":"h","s":["Unexploded weapons in border and boundary areas"]},{"k":"p","s":["There is some risk from unexploded weapons:"]},{"k":"li","s":["along the administrative boundary lines with South Ossetia and Abkhazia"]},{"k":"li","s":["near the border with Azerbaijan (Red Bridge area in particular)"]},{"k":"p","s":["Areas where there might be unexploded weapons are not always marked. Go with a local guide or tour group if visiting these areas."]},{"k":"h","s":["Border with Azerbaijan"]},{"k":"p","s":["The land border with Azerbaijan has been closed since the start of the COVID-19 pandemic."]},{"k":"p","s":["If you visit the Udabno caves at the Davit Gareja monastery site, take care not to cross the Georgia-Azerbaijan border. It is unmarked in this area and disputed. There are border guides in the area – seek their advice if you’re unsure."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Georgia","https://travelhealthpro.org.uk/country/87/georgia"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["Altitude sickness is a risk in parts of Georgia, including Gudauri ski resort, Mount Kazbegi, and Mount Tetnuldi. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"p","s":["Health risks include:"]},{"k":"li","s":["rabies – treatment is available in Tbilisi and major towns. If you’re bitten or scratched by a dog, get medical attention immediately."]},{"k":"li","s":["venomous snakes (vipers), particularly in early summer – few medical facilities outside major towns have anti-venom"]},{"k":"li","s":["varying water quality – bottled water is widely available"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["For more information on travelling with medicines to Georgia, see ",["Entry requirements","https://www.gov.uk/foreign-travel-advice/georgia/entry-requirements#travelling-with-medicines"],". For information on the legal status of a specific medicine, contact the ",["Georgian Embassy in the UK","https://uk.mfa.gov.ge/en"],"."]},{"k":"h","s":["Healthcare in Georgia"]},{"k":"p","s":["The UK does not have a reciprocal healthcare agreement with Georgia. You or your travel insurer will need to pay for all treatment as it’s provided."]},{"k":"p","s":["Medical facilities in Tbilisi are available but can be expensive. Outside Tbilisi, medical facilities are limited."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Georgia","https://www.gov.uk/government/publications/list-of-medical-facilities-in-georgia"]," where some staff will speak English."]},{"k":"p","s":["There is also ",["guidance on healthcare if you’re living in Georgia","https://www.gov.uk/guidance/living-in-georgia#healthcare-in-georgia"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Georgia"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Georgia"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Georgia"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Georgia"]," in Georgia"]},{"k":"li","s":["dealing with a ",["death in Georgia","https://www.gov.uk/government/publications/georgia-bereavement-pack-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in Georgia","https://www.gov.uk/government/publications/georgia-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/georgia/british-embassy-tbilisi"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/georgia/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Georgia","https://www.gov.uk/government/publications/overseas-business-risk-georgia"]," on how to manage political, economic, and business security-related risks."]}],"chars":23849,"change":"Updated information about the political situation ('Safety and security' page)."},"https://theconversation.com/boikot-rans-buktikan-usaha-lokal-kritis-terhadap-aksi-politik-meski-cuan-taruhannya-295650":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"eb513a3b2457344bd3dd5899286217fd926be28d60b4369b9a7a8560994e16f4","read":"https://theconversation.com/boikot-rans-buktikan-usaha-lokal-kritis-terhadap-aksi-politik-meski-cuan-taruhannya-295650","bytes":179087,"x":"fulltext v1","title":"Boikot Rans buktikan usaha lokal kritis terhadap aksi politik meski cuan taruhannya","by":[{"n":"Ibnu Darmawan","r":"Dosen, Universitas Islam Indonesia (UII) Yogyakarta"}],"pub":"2026-11-02T07:00:28Z","mod":"","blocks":[{"k":"p","s":["• Raffi Ahmad dituding melakukan ‘agenda setting’ dalam momen peringatan Sumpah Pemuda."]},{"k":"p","s":["• Dinamika ini memicu kemarahan masyarakat, tidak hanya kepada pribadi Raffi Ahmad tapi Rans Entertainment."]},{"k":"p","s":["• Rans Carnival yang harusnya berlangsung meriah, jadi sepi peserta dan pengunjung."]},{"k":"p","s":["Plataran parkir Stadion Maguwoharjo, Sleman (Daerah Istimewa Yogyakarta), sejak Kamis malam, 29 Oktober 2026 sudah ramai aktivitas. Lokasi ini merupakan tempat perhalatan Rans Carnival yang rencananya digelar Sabtu-Ahad, 31 Oktober-1 November 2026."]},{"k":"p","s":["Namun, keramaian itu bukan aktivitas persiapan acara, melainkan para tenant yang sedang merapikan lapaknya sebelum acara dimulai."]},{"k":"p","s":["Aksi ini dipicu oleh mundurnya musisi utama seperti ",["Guyon Waton, OM Wawes, dan Tipe-X","https://tirto.id/tipe-x-hingga-guyon-waton-mundur-batal-tampil-di-rans-carnival-hErZ"],", dan adanya gelombang boikot warganet kepada pemilik festival, Raffi Ahmad, yang beberapa waktu lalu hadir dalam Deklarasi Sumpah Pemuda di Jakarta."]},{"k":"p","s":["Bagi pelaku UMKM, keputusan mundur ini jelas menjadi pertaruhan bagi kelangsungan usahanya. Penjual donat, cuanki, hingga minuman kelapa yang terlanjur menyetok banyak porsi makanan basah terpaksa menelan risiko kerugian modal dalam sekejap."]},{"k":"p","s":["Meski tampak seperti kekacauan manajerial sebuah festival, peristiwa di Maguwoharjo ini menyimpan makna sosiologis dan komunikasi publik yang jauh lebih dalam."]},{"k":"p","s":["Fenomena ini memperlihatkan pergeseran dalam relasi bisnis dan publik: bagaimana pelaku UMKM lokal dan musisi mempraktikkan brand activism, menolak terseret politisasi elite, dan menemukan daya tawar kolektif mereka bersama warga setempat."]},{"k":"p","s":["Read more: ",["Fasilitas umum kerap rusak saat demo: Bagaimana taksiran kerugiannya?","https://theconversation.com/fasilitas-umum-kerap-rusak-saat-demo-bagaimana-taksiran-kerugiannya-269036"]]},{"k":"h","s":["Blunder Raffi Ahmad dan penolakan publik"]},{"k":"p","s":["Peristiwa di Maguwoharjo memberi pesan kepada masyarakat luas bahwa batas antara panggung hiburan, brand, dan pusaran kekuasaan kini kian tipis."]},{"k":"p","s":["Ketika seorang pemuka seperti ",["Raffi Ahmad","https://www.cnnindonesia.com/ekonomi/20260710183213-92-1379295/daftar-pemilik-saham-rans-ada-raffi-ahmad-hingga-kaesang-pangarep"]," selaku co-founder Rans dan juga ",["utusan khusus presiden","https://nasional.kompas.com/read/2024/10/22/14552131/tugas-raffi-ahmad-sebagai-utusan-khusus-presiden"]," bermanuver politik praktis, ",["entitas bisnisnya akan selalu melekat dan dipertaruhkan","https://www.researchgate.net/publication/375961618_Pengantar_Ekonomi_Politik"],"."]},{"k":"p","s":["Semua bermula ketika Raffi Ahmad, influencer ",["Willie Salim","https://hot.detik.com/celeb/d-8733510/permintaan-maaf-willie-salim-usai-hadiri-deklarasi-sumpah-pemuda"],", dan sejumlah kelompok yang mengaku mahasiswa merayakan momen Sumpah Pemuda di Bundaran Hotel Indonesia Jakarta, 29 Oktober 2026 silam."]},{"k":"p","s":["Belakangan, publik mendapati massa yang diboyong bersama mereka ternyata mahasiswa gadungan. Inilah yang memicu kemarahan publik dan warganet."]},{"k":"p","s":["Untuk sosok setenar Raffi, setiap tindakan politik yang memicu kontroversi akan langsung berdampak dan menyeret pihak-pihak di sekitarnya, termasuk mitra dagang, tenant kecil, hingga artis yang sudah berkontrak dengan Rans Carnival di Yogyakarta."]},{"k":"p","s":["Fenomena mundurnya para tenant dan artis dari Rans Carnival merupakan penanda positif tentang kesadaran politik masyarakat. Ini berarti mereka menyadari bahwa modal terpenting mereka bukanlah omzet yang dihasilkan dari festival sesaat, melainkan legitimasi sosial dan kepercayaan masyarakat dan konsumen harian di sekitarnya."]},{"k":"p","s":["Read more: ",["Slogan protes sebagai bentuk luapan emosi, solidaritas, dan pembangkangan politik","https://theconversation.com/slogan-protes-sebagai-bentuk-luapan-emosi-solidaritas-dan-pembangkangan-politik-264786"]]},{"k":"h","s":["Aksi penolakan campur tangan politik dalam bisnis"]},{"k":"p","s":["Menyelamatkan reputasi di hadapan publik lokal menjadi keputusan yang jauh lebih rasional dibanding memaksakan diri bertahan di panggung yang telah kehilangan restu warganya. Ini meskipun kemungkinan para tenant yang mundur justru mengalami masalah keuangan karena membatalkan partisipasi dalam Rans Carnival."]},{"k":"p","s":["Kesadaran menjaga reputasi dan modal simbolis brand dengan berani mengambil sikap tegas—bukan bersikap netral—terhadap isu sosial-politik yang menyangkut nilai konsumennya dikenal sebagai ",["brand activism","https://doi.org/10.2139/ssrn.4028569"]," (aktivisme merek)."]},{"k":"p","s":["Pada akhirnya keputusan mundur para pedagang kecil di Jogja menegaskan bahwa ",["aroma politis dari suatu panggung","https://doi.org/10.1016/j.jbusres.2025.115704"]," perlu dihindari meskipun harus kehilangan sorotan perhatian dan perbincangan masyarakat."]},{"k":"p","s":["Dalam kajian komunikasi, relasi antara konsumen dan brand telah bergeser menjadi kontrak sosial berbasis nilai. Studi yang dilakukan oleh ",["Helen O’Sullivan dan tim","https://doi.org/10.3390/encyclopedia6010027"]," tahun 2026 menegaskan: konsumen modern khususnya kelompok muda melihat sikap diam dalam krisis sosial-politik bukan sebagai kenetralan yang bijak, melainkan sebagai bentuk pembiaran."]},{"k":"p","s":[["Rans Carnival","https://doi.org/10.3390/encyclopedia6010027"]," sedang dituding sarat aroma politik yang ditakuti mendapatkan tudingan pengkhianatan nilai komunitas karena konsumen yang mementingkan etika bisnis sebelum memutuskan setia pada suatu brand."]},{"k":"p","s":["Read more: ",["Nobel Ekonomi 2026 buktikan harapan dan keresahan warga amat krusial dalam menstabilkan perekonomian","https://theconversation.com/nobel-ekonomi-2026-buktikan-harapan-dan-keresahan-warga-amat-krusial-dalam-menstabilkan-perekonomian-293827"]]},{"k":"p","s":["Karena itu, risiko dijauhi dan diboikot selamanya oleh pelanggan lokal di Jogja jelas jauh lebih mematikan ketimbang sekadar merelakan potensi laba dua hari di arena festival."]},{"k":"h","s":["Gerakan warga bantu warga"]},{"k":"p","s":["Peristiwa ini sekaligus mematahkan anggapan bahwa keberlangsungan usaha kecil kerap bergantung pada promotor festival besar. Penarikan diri yang serempak menunjukkan bahwa UMKM lokal sebagai komunitas akar rumput memiliki agensi dan daya tawar politiknya sendiri."]},{"k":"p","s":["Setelah sorotan acara Rans di Maguwoharjo tersambung secara alami dengan ruang percakapan digital, salah satunya di Threads, warganet tidak sekadar meluapkan amarah tetapi juga bergerak mengorganisasi perlindungan ekonomi secara sukarela."]},{"k":"p","s":["Warganet membuat gerakan ajakan terbuka bagi warga untuk beramai-ramai “nglarisi” sebagai bentuk solidaritas beredar luas, disambut dengan riuhnya dukungan warganet yang menaruh simpati, salah satunya dengan jargon “ ",["Josjis warga Jogja","https://x.com/cariaeosa/status/2116487320459190770"],"”."]},{"k":"p","s":["Fenomena ini memperlihatkan bagaimana percakapan di media sosial bertransformasi menjadi ",["aksi kolektif di lapangan","https://doi.org/10.2139/ssrn.4028569"]," (online-to-offline collective action), membentuk ",["jaring pengaman komunitas (community cushioning) yang melindungi pedagang lokal","https://doi.org/10.3390/encyclopedia6010027"],"."]},{"k":"p","s":["Pada akhirnya, modal sosial dan kedekatan kultural antarwarga membuktikan sanggup menjaga daya tahan ekonomi mikro tanpa harus menundukkan diri pada panggung hiburan nasional."]},{"k":"p","s":["Mekanisme psikologi publik ini dapat dijelaskan lewat riset ",["Sumin Kim dan Hongwei He","https://doi.org/10.1016/j.jbusres.2025.115704"]," tahun 2025. Ketika publik menilai suatu entitas bertindak atas dasar motif mementingkan diri (egoistic motive) dari Raffi Ahmad, respons yang muncul adalah kemarahan (anger) yang melahirkan pemboikotan."]},{"k":"p","s":["Sebaliknya, ketika tindakan dinilai bersumber dari ",["ketulusan nilai moral","https://doi.org/10.1016/j.jbusres.2025.115704"],", empati publik yang muncul mendorong mereka melakukan pembelaan secara sukarela."]},{"k":"p","s":["Read more: ",["Usai sukses di ASEAN Cup 2026, apakah Rans bisa menayangkan Liga Inggris gratis di YouTube?","https://theconversation.com/usai-sukses-di-asean-cup-2026-apakah-rans-bisa-menayangkan-liga-inggris-gratis-di-youtube-294030"]]}],"chars":6307}};
